1	/**
2	 * SFCC-83/84 build plan step E1 — asserts only this component's own branch-selection contract
3	 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given a `recommender` and
4	 * `useEinstein()`'s own `recommendations`, does it render `ZimmRecentlyViewedRail`,
5	 * `ProductScroller`, or nothing at all. `ZimmRecentlyViewedRail`, `ProductScroller`, and
6	 * `selectRecentlyViewedCard` are all mocked at the smallest surface — their own internals already
7	 * have their own coverage elsewhere (`zimmRecentlyViewedRail/index.test.tsx`,
8	 * `recentlyViewedCard.test.ts`; base `ProductScroller` is untouched vendor code).
9	 *
10	 * **Rewritten for build plan step E1** — the interim mechanism's own hook mocks are gone (both
11	 * hooks are deleted in build plan step E4); every Recently-Viewed test case below now drives its
12	 * scenario entirely through the already-present `mockUseEinstein`, matching the exact pattern the
13	 * "any other recommender" test already used before this rewrite. Product fixtures use a real `id`
14	 * field (`RecentlyViewedProduct`, `recentlyViewedCard.ts`'s own alias for
15	 * `ShopperProductsTypes.Product`) since that is what a hydrated Einstein rec looks like by the
16	 * time this component reads it (see index.tsx's own module docblock, point 2).
17	 */
18	import React from 'react';
19	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
20	import { render, screen } from '@testing-library/react';
21	import { MemoryRouter } from 'react-router-dom';
22	import { ChakraProvider } from '@chakra-ui/react';
23	import { IntlProvider } from 'react-intl';
24	import { EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
25	import theme from 'app/theme';
26	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
27	import { selectRecentlyViewedCard, type RecentlyViewedProduct } from '../../utils/recentlyViewedCard';
28	import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
29	import RecommendedProducts, { type RecommendedProductsProps } from '.';
30	
31	// Smallest-surface mocks throughout — see module docblock above for why each of these is safe to
32	// stub rather than exercise for real in this file.
33	
34	vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
35	  default: vi.fn(),
36	}));
37	
38	vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
39	  default: () => ({ sendViewRecommendations: vi.fn() }),
40	}));
41	
42	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-customer', () => ({
43	  useCurrentCustomer: () => ({ data: { customerId: 'test-customer-id' } }),
44	}));
45	
46	// Real use-intersection-observer.js already degrades to `true` under jsdom (no global
47	// IntersectionObserver), but stubbed anyway per this step's own brief, for a deterministic
48	// `isOnScreen` this file doesn't otherwise need to reason about.
49	vi.mock('@salesforce/retail-react-app/app/hooks/use-intersection-observer', () => ({
50	  default: () => false,
51	}));
52	
53	vi.mock('@salesforce/retail-react-app/app/hooks/use-wish-list', () => ({
54	  useWishList: () => ({ data: undefined }),
55	}));
56	
57	vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
58	  useToast: () => vi.fn(),
59	}));
60	
61	vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
62	  default: () => vi.fn(),
63	}));
64	
65	// `buildUrl` is the one piece of this hook the See-Full-History link actually uses
66	// (site/locale-prefixing `RECENTLY_VIEWED_ROUTE`); a fixed non-default-site prefix here proves
67	// the link is correctly site-prefixed on a non-default storefront without needing the real
68	// multi-site provider context.
69	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
70	  default: () => ({ buildUrl: (path: string) => `/en-GB${path}` }),
71	}));
72	
73	vi.mock('@salesforce/commerce-sdk-react', () => ({
74	  useShopperCustomersMutation: () => ({ mutateAsync: vi.fn() }),
75	}));
76	
77	// ProductScroller is a real `forwardRef` component (product-scroller/index.jsx) — mocked as one
78	// too, rather than a plain function, so `<ProductScroller ref={ref} .../>` doesn't trip React's
79	// "function components cannot be given refs" warning for no reason.
80	vi.mock('@salesforce/retail-react-app/app/components/product-scroller', () => ({
81	  default: React.forwardRef(function ProductScrollerStub(_props: unknown, ref: React.Ref<HTMLDivElement>) {
82	    return <div ref={ref} data-testid="product-scroller-stub" />;
83	  }),
84	}));
85	
86	// Relative paths matching index.tsx's own imports exactly — see overrideStyling.md's
87	// "Importing an already-overridden component" doctrine cited there.
88	vi.mock('../ui-kits/organisms/zimmRecentlyViewedRail', () => ({
89	  ZimmRecentlyViewedRail: vi.fn(() => <div data-testid="zimm-recently-viewed-rail-stub" />),
90	}));
91	
92	vi.mock('../../utils/recentlyViewedCard', () => ({
93	  selectRecentlyViewedCard: vi.fn(),
94	}));
95	
96	// jsdom has no matchMedia implementation, and index.tsx's own `useRecentlyViewedRailVisibleCount`
97	// call (the See-Full-History trigger threshold) uses it internally via `useMediaQuery` — a
98	// per-file polyfill, not a change to the frozen vitest.setup.ts (Tier 1), matching the identical,
99	// already-established precedent at drawer-menu/index.test.tsx (Chakra Drawer's own
100	// useBreakpointValue usage). `matches: false` unconditionally is what makes both underlying
101	// `useMediaQuery` checks resolve to their smallest/mobile fallback in this environment — exactly
102	// what the See-Full-History tests below are written against.
103	beforeEach(() => {
104	  Object.defineProperty(window, 'matchMedia', {
105	    writable: true,
106	    value: vi.fn().mockImplementation((query: string) => ({
107	      matches: false,
108	      media: query,
109	      onchange: null,
110	      addListener: vi.fn(),
111	      removeListener: vi.fn(),
112	      addEventListener: vi.fn(),
113	      removeEventListener: vi.fn(),
114	      dispatchEvent: vi.fn(),
115	    })),
116	  });
117	});
118	
119	const mockUseEinstein = vi.mocked(useEinstein);
120	const mockSelectRecentlyViewedCard = vi.mocked(selectRecentlyViewedCard);
121	const mockZimmRecentlyViewedRail = vi.mocked(ZimmRecentlyViewedRail);
122	
123	// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
124	// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
125	// same doctrine recentlyViewedCard.test.ts documents as "G1". Shaped with a real `id` field
126	// (RecentlyViewedProduct — recentlyViewedCard.ts's own alias for
127	// `ShopperProductsTypes.Product`), matching what a hydrated Einstein rec looks like by the time
128	// this component reads it.
129	const mockRecentlyViewedProducts: RecentlyViewedProduct[] = [
130	  { id: 'rec-1', name: 'Product One' } as RecentlyViewedProduct,
131	  { id: 'rec-2', name: 'Product Two' } as RecentlyViewedProduct,
132	];
133	
134	/** A real Recently-Viewed `useEinstein().recommendations` response shape, for the
135	 *  Recently-Viewed-branch tests below — `recommenderName` matches the actual recommender string
136	 *  (see index.tsx's own module docblock re: `PDP_RECENTLY_VIEWED`/`CART_RECENTLY_VIEWED`
137	 *  resolving identically). */
138	const buildRecentlyViewedRecommendations = (recs: RecentlyViewedProduct[]) => ({
139	  recommenderName: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED,
140	  recoUUID: 'test-rv-reco-uuid',
141	  displayMessage: 'Recently Viewed',
142	  recs,
143	});
144	
145	// A real Einstein response shape — still used by the "any other recommender" test below, since
146	// only the Recently-Viewed branch's data source changed (build plan step E1).
147	const mockRecommendations = {
148	  recommenderName: 'might-also-like-einstein',
149	  recoUUID: 'test-reco-uuid',
150	  displayMessage: 'You Might Also Like',
151	  recs: [
152	    { productId: 'reco-1', name: 'Recommended One' },
153	    { productId: 'reco-2', name: 'Recommended Two' },
154	  ],
155	};
156	
157	// `route` defaults to '/' — the component calls `useLocation()` unconditionally (Cart
158	// exclusion, 2026-09-10), so every render needs a Router ancestor regardless of what a given
159	// test actually asserts on. Only the dedicated Cart-exclusion test below passes a real route.
160	const renderRecommendedProducts = (props: Partial<RecommendedProductsProps> = {}, route = '/') =>
161	  render(
162	    <MemoryRouter initialEntries={[route]}>
163	      <IntlProvider locale="en-AU" messages={{}}>
164	        <ChakraProvider theme={theme}>
165	          <RecommendedProducts recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE} {...props} />
166	        </ChakraProvider>
167	      </IntlProvider>
168	    </MemoryRouter>,
169	  );
170	
171	afterEach(() => {
172	  vi.clearAllMocks();
173	});
174	
175	describe('RecommendedProducts — Recently Viewed branch (SFCC-83/84, build plan E1)', () => {
176	  test('recommender=PDP_RECENTLY_VIEWED with recs renders ZimmRecentlyViewedRail, not ProductScroller, and fires getRecommendations', () => {
177	    const mockGetRecommendations = vi.fn();
178	    mockUseEinstein.mockReturnValue({
179	      isLoading: false,
180	      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
181	      getZoneRecommendations: vi.fn(),
182	      getRecommendations: mockGetRecommendations,
183	      sendClickReco: vi.fn(),
184	      sendViewReco: vi.fn(),
185	    });
186	    // rec-2 deliberately maps to `null` (e.g. no usable image/name) — proves the branch's own
187	    // `.filter()` drops it instead of forwarding a null card or crashing.
188	    mockSelectRecentlyViewedCard.mockImplementation((product) =>
189	      product?.id === 'rec-2'
190	        ? null
191	        : {
192	            id: product?.id ?? '',
193	            href: `/product/${product?.id ?? ''}`,
194	            name: product?.name ?? '',
195	            primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
196	            currentPrice: undefined,
197	          },
198	    );
199	
200	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });
201	
202	    expect(screen.getByTestId('zimm-recently-viewed-rail-stub')).toBeInTheDocument();
203	    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
204	
205	    // Build plan E1, edit 1: the fetch-effect early return for this recommender is gone —
206	    // getRecommendations now fires for it exactly like the other four recommenders already do.
207	    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, undefined);
208	
209	    // Branch's own mapping contract (not the rail's internals): the null-mapped product is
210	    // dropped, the surviving card carries the container-assigned `headingLevel`/`variation`, and
211	    // `title` is passed straight through from the caller's own prop — no `recommendations`
212	    // fallback.
213	    //
214	    // Renders twice, not once — `useRecentlyViewedRailVisibleCount`'s own `useMediaQuery` calls
215	    // add a second, legitimate render pass (matching this environment's SSR-safe
216	    // mount-with-fallback-then-resolve pattern). Not a regression in this branch's own logic;
217	    // asserting both calls agree is what actually matters here, not the raw count.
218	    expect(mockZimmRecentlyViewedRail.mock.calls.length).toBeGreaterThanOrEqual(1);
219	    const allCallsAgree = mockZimmRecentlyViewedRail.mock.calls.every(
220	      ([callProps]) => JSON.stringify(callProps) === JSON.stringify(mockZimmRecentlyViewedRail.mock.calls[0][0]),
221	    );
222	    expect(allCallsAgree).toBe(true);
223	    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
224	    expect(railProps.title).toBe('Recently Viewed');
225	    expect(railProps.cards).toHaveLength(1);
226	    expect(railProps.cards[0]).toMatchObject({
227	      id: 'rec-1',
228	      headingLevel: 'h3',
229	      variation: 'recentlyViewed',
230	    });
231	  });
232	
233	  test('any other recommender still calls getRecommendations and renders via ProductScroller, not the rail', () => {
234	    const mockGetRecommendations = vi.fn();
235	    mockUseEinstein.mockReturnValue({
236	      isLoading: false,
237	      recommendations: mockRecommendations,
238	      getZoneRecommendations: vi.fn(),
239	      getRecommendations: mockGetRecommendations,
240	      sendClickReco: vi.fn(),
241	      sendViewReco: vi.fn(),
242	    });
243	
244	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });
245	
246	    expect(screen.getByTestId('product-scroller-stub')).toBeInTheDocument();
247	    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
248	    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
249	    // Proves the RV branch is recommender-gated (would fail if the `if (recommender ===
250	    // PDP_RECENTLY_VIEWED)` check were accidentally dropped or widened) and that this sibling
251	    // recommender still fetches its own recommendations exactly as before.
252	    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE, undefined);
253	  });
254	
255	  test.each([
256	    ['recs is an empty array (AC 8: a real zero-history response)', buildRecentlyViewedRecommendations([])],
257	    ["recommendations has not resolved yet (useEinstein()'s own pre-fetch initial value)", []],
258	    ['recs is undefined on the recommendations object', { recommenderName: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED }],
259	  ])('renders null — no rail, no scroller — when %s', (_label, recommendationsValue) => {
260	    mockUseEinstein.mockReturnValue({
261	      isLoading: false,
262	      recommendations: recommendationsValue,
263	      getZoneRecommendations: vi.fn(),
264	      getRecommendations: vi.fn(),
265	      sendClickReco: vi.fn(),
266	      sendViewReco: vi.fn(),
267	    });
268	
269	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });
270	
271	    // Neither branch's component rendered — the component itself returns `null` here. Not
272	    // asserted via `container.toBeEmptyDOMElement()`: ChakraProvider always injects its own
273	    // internal `<span id="__chakra_env">` marker regardless of what this component renders, so
274	    // an empty-container check would be asserting on Chakra's own internals, not this
275	    // component's contract.
276	    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
277	    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
278	    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
279	  });
280	
281	  test('on the Cart route, renders null even when recs has items (Marcel, 2026-09-10: "no recently viewed on cart")', () => {
282	    // Deliberately non-empty recs — proves the Cart exclusion wins even when there IS real
283	    // Einstein data to show, not just the already-covered "nothing to show anyway" case above.
284	    // Cart has no Zimmermann page override of its own; its base page passes
285	    // recommender={EINSTEIN_RECOMMENDERS.CART_RECENTLY_VIEWED}, which resolves to the exact same
286	    // string as PDP_RECENTLY_VIEWED (see index.tsx's own isCartPage comment) — this recommender
287	    // value alone cannot distinguish the two, so this test renders at the real recommender value
288	    // used everywhere else in this suite and asserts the *route* is what suppresses it.
289	    const mockGetRecommendations = vi.fn();
290	    mockUseEinstein.mockReturnValue({
291	      isLoading: false,
292	      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
293	      getZoneRecommendations: vi.fn(),
294	      getRecommendations: mockGetRecommendations,
295	      sendClickReco: vi.fn(),
296	      sendViewReco: vi.fn(),
297	    });
298	
299	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED }, '/cart');
300	
301	    expect(screen.queryByTestId('zimm-recently-viewed-rail-stub')).not.toBeInTheDocument();
302	    expect(screen.queryByTestId('product-scroller-stub')).not.toBeInTheDocument();
303	    // Accepted "wasted call" (build plan E1's own "Cart wasted-call note"): the fetch-effect now
304	    // fires unconditionally for every recommender, Cart included, even though the render branch
305	    // above returns null for it — one harmless, unread network call on a descoped surface.
306	    // Documented here rather than left as an untested assumption.
307	    expect(mockGetRecommendations).toHaveBeenCalledWith(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, undefined);
308	  });
309	
310	  // The See-Full-History link. jsdom resolves both `useMediaQuery` checks inside
311	  // `useRecentlyViewedRailVisibleCount` to `false` (see the `matchMedia` polyfill above), so
312	  // these fixtures are sized against `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base` (2) rather than
313	  // asserting anything about actual breakpoint switching — that's Chakra's own concern, not this
314	  // component's. What this component owns is purely "count vs threshold", which is
315	  // breakpoint-agnostic to test.
316	  test('See-Full-History link appears when available cards exceed the visible count at this breakpoint', () => {
317	    const ids = ['rec-1', 'rec-2', 'rec-3'];
318	    mockUseEinstein.mockReturnValue({
319	      isLoading: false,
320	      recommendations: buildRecentlyViewedRecommendations(
321	        ids.map((id) => ({ id, name: `Product ${id}` }) as RecentlyViewedProduct),
322	      ),
323	      getZoneRecommendations: vi.fn(),
324	      getRecommendations: vi.fn(),
325	      sendClickReco: vi.fn(),
326	      sendViewReco: vi.fn(),
327	    });
328	    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
329	      id: product?.id ?? '',
330	      href: `/product/${product?.id ?? ''}`,
331	      name: product?.name ?? '',
332	      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
333	      currentPrice: undefined,
334	    }));
335	
336	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });
337	
338	    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
339	    // Site/locale-prefixed via useMultiSite's buildUrl (mocked above to a non-default `/en-GB`
340	    // prefix) — the rail itself must never build this prefix, only the container.
341	    expect(railProps.seeAllHref).toBe('/en-GB/recently-viewed');
342	    expect(railProps.seeAllLabel).toBe('See Full History');
343	  });
344	
345	  test('See-Full-History link is absent when available cards do not exceed the visible count at this breakpoint', () => {
346	    const ids = ['rec-1', 'rec-2'];
347	    mockUseEinstein.mockReturnValue({
348	      isLoading: false,
349	      recommendations: buildRecentlyViewedRecommendations(
350	        ids.map((id) => ({ id, name: `Product ${id}` }) as RecentlyViewedProduct),
351	      ),
352	      getZoneRecommendations: vi.fn(),
353	      getRecommendations: vi.fn(),
354	      sendClickReco: vi.fn(),
355	      sendViewReco: vi.fn(),
356	    });
357	    mockSelectRecentlyViewedCard.mockImplementation((product) => ({
358	      id: product?.id ?? '',
359	      href: `/product/${product?.id ?? ''}`,
360	      name: product?.name ?? '',
361	      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
362	      currentPrice: undefined,
363	    }));
364	
365	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED });
366	
367	    const railProps = mockZimmRecentlyViewedRail.mock.calls[0][0];
368	    expect(railProps.seeAllHref).toBeUndefined();
369	    expect(railProps.seeAllLabel).toBeUndefined();
370	  });
371	});
